def check_modular_m(m):
    from itertools import combinations

    def get_coloring(m):
        coloring = {}
        for i, j in combinations(range(m), 2):
            coloring[(i, j)] = (i + j) % m
        return coloring

    coloring = get_coloring(m)
    color_sets = set()
    for triangle in combinations(range(m), 3):
        u, v, w = triangle
        c1 = coloring[tuple(sorted((u, v)))]
        c2 = coloring[tuple(sorted((v, w)))]
        c3 = coloring[tuple(sorted((u, w)))]
        if len({c1, c2, c3}) < 3:
            return False, "not 3-colored"
        color_sets.add(tuple(sorted((c1, c2, c3))))

    if len(color_sets) == m * (m - 1) * (m - 2) // 6:
        return True, "works"
    else:
        return False, f"only {len(color_sets)} sets"

for m in range(3, 21, 2):
    res, msg = check_modular_m(m)
    print(f"m={m}: {res} ({msg})")

